agent='math81_boundary_classical_mid'
cases=['empty','zero','one','degenerate','endpoints','nonempty-choice','iff-forward']
patches=[]; reviews=[]
for i,s in enumerate(work['subjects']):
 raw=pathlib.Path(s['source']).read_bytes(); case_reviews=[]
 for r in s['rows']:
  original=copy.deepcopy(r['original']); case=original['case']; col=6 if case.startswith('iff-') else cases.index(case)
  note=notes[i][col]; status='checked' if note.startswith('C ') else 'not_applicable'; reason=note[2:]
  # Preserve a valid, nonmechanical exclusion verbatim and openly adjudicate its repeated template.
  # Checked rows receive actual current proof evidence, rather than stale generic step pointers.
  if status=='not_applicable' and original['status']=='not_applicable':
   proposed=copy.deepcopy(original)
   if any(f['kind']=='template' for f in r['candidate_findings']): proposed['template_review']={'upheld':True,'by':agent,'reason':reason}
   if any(f['kind']=='contradicted' for f in r['candidate_findings']): proposed['reviewed']={'upheld':True,'by':agent,'reason':reason}
   action='uphold exclusion with specific mathematical review'
  else:
   proposed={'case':case,'status':status,('evidence' if status=='checked' else 'reason'):reason}
   action='replace boundary disposition/evidence from actual current body'
  patches.append({'id':s['id'],'case':case,'original':original,'proposed':proposed,'evidence':reason})
  case_reviews.append({'case':case,'status':status,'evidence':reason,'action':action})
 reviews.append({'id':s['id'],'source':s['source'],'source_raw_sha256_at_read':hashlib.sha256(raw).hexdigest(),'read_scope':'Current entire Definition/Statement/Example/Statement refuted, all Facts & Assumptions, and complete Proof/Verification/Counterexample where supplied; no external-source reading claimed.','assessment':'Boundary review of actual local mathematics; not a whole-item publication audit.','case_reviews':case_reviews})
assert len(notes)==127
assert len(patches)==857,len(patches)
(OUT/'row-patches.json').write_text(json.dumps(patches,indent=2,ensure_ascii=False)+'\n')
(OUT/'item-reading-review.json').write_text(json.dumps({'run':work['run'],'by':agent,'items':reviews},indent=2,ensure_ascii=False)+'\n')
print('Prepared',len(patches),'rows for',len(reviews),'items')
